    Bug 1716745 - Fix CalDav import of ICS events with special characters in the UID. r=darktrojan


    Makes sure the PUT request has a valid URL to avoid import errors.

    Differential Revision: https://phabricator.services.mozilla.com/D215445

diff --git a/calendar/providers/caldav/CalDavCalendar.sys.mjs b/calendar/providers/caldav/CalDavCalendar.sys.mjs
index bde9f71aca7..7bc55d5871f 100644
--- a/calendar/providers/caldav/CalDavCalendar.sys.mjs
+++ b/calendar/providers/caldav/CalDavCalendar.sys.mjs
@@ -26,6 +26,7 @@ import { CalReadableStreamFactory } from "resource:///modules/CalReadableStreamF

 var XML_HEADER = '<?xml version="1.0" encoding="UTF-8"?>\n';
 var MIME_TEXT_XML = "text/xml; charset=utf-8";
+var FORBIDDEN_PATH_CHARACTERS = /[^a-zA-Z0-9_\-\.]/g;

 var cIOL = Ci.calIOperationListener;
 const lazy = {};
@@ -467,7 +468,7 @@ CalDavCalendar.prototype = {
       return this.mItemInfoCache[aItem.id].locationPath;
     }
     // New items just use id.ics
-    return aItem.id + ".ics";
+    return aItem.id.replaceAll(FORBIDDEN_PATH_CHARACTERS, "_") + ".ics";
   },

   getProperty(aName) {
